            return FfiConverterLong.lift(
    callWithHandle {
    uniffiRustCallWithError(MimirException) { _status ->
    UniffiLib.uniffi_mimir_fn_method_mimirapp_accept_contact_request(
        it,
        FfiConverterLong.lower(`requestId`),_status)
